  .lh-topbar {
    position: sticky;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    display: flex;
    align-items: center;
    height: var(--topbar-height);
    padding: var(--topbar-padding);
    font-size: var(--report-font-size-secondary);
    background-color: var(--topbar-background-color);
    border-bottom: 1px solid var(--color-gray-200);
  }

  .lh-topbar__logo {
    width: var(--topbar-logo-size);
    height: var(--topbar-logo-size);
    user-select: none;
    flex: none;
  }

  .lh-topbar__url {
    margin: var(--topbar-padding);
    text-decoration: none;
    color: var(--report-text-color);
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
  }

  .lh-tools {
    display: flex;
    align-items: center;
    margin-left: auto;
    will-change: transform;
    min-width: var(--report-icon-size);
  }
  .lh-tools__button {
    width: var(--report-icon-size);
    min-width: 24px;
    height: var(--report-icon-size);
    cursor: pointer;
    margin-right: 5px;
    /* This is actually a button element, but we want to style it like a transparent div. */
    display: flex;
    background: none;
    color: inherit;
    border: none;
    padding: 0;
    font: inherit;
    outline: inherit;
  }
  .lh-tools__button svg {
    fill: var(--tools-icon-color);
  }
  .lh-dark .lh-tools__button svg {
    filter: invert(1);
  }
  .lh-tools__button.lh-active + .lh-tools__dropdown {
    opacity: 1;
    clip: rect(-1px, 194px, 242px, -3px);
    visibility: visible;
  }
  .lh-tools__dropdown {
    position: absolute;
    background-color: var(--report-background-color);
    border: 1px solid var(--report-border-color);
    border-radius: 3px;
    padding: calc(var(--default-padding) / 2) 0;
    cursor: pointer;
    top: 36px;
    right: 0;
    box-shadow: 1px 1px 3px #ccc;
    min-width: 125px;
    clip: rect(0, 164px, 0, 0);
    visibility: hidden;
    opacity: 0;
    transition: all 200ms cubic-bezier(0,0,0.2,1);
  }
  .lh-tools__dropdown a {
    color: currentColor;
    text-decoration: none;
    white-space: nowrap;
    padding: 0 6px;
    line-height: 2;
  }
  .lh-tools__dropdown a:hover,
  .lh-tools__dropdown a:focus {
    background-color: var(--color-gray-200);
    outline: none;
  }
  /* save-gist option hidden in report. */
  .lh-tools__dropdown a[data-action='save-gist'] {
    display: none;
  }

  .lh-locale-selector {
    width: 100%;
    color: var(--report-text-color);
    background-color: var(--locale-selector-background-color);
    padding: 2px;
  }
  .lh-tools-locale {
    display: flex;
    align-items: center;
    flex-direction: row-reverse;
  }
  .lh-tools-locale__selector-wrapper {
    transition: opacity 0.15s;
    opacity: 0;
    max-width: 200px;
  }
  .lh-button.lh-tool-locale__button {
    height: var(--topbar-height);
    color: var(--tools-icon-color);
    padding: calc(var(--default-padding) / 2);
  }
  .lh-tool-locale__button.lh-active + .lh-tools-locale__selector-wrapper {
    opacity: 1;
    clip: rect(-1px, 194px, 242px, -3px);
    visibility: visible;
    margin: 0 4px;
  }

  @media screen and (max-width: 964px) {
    .lh-tools__dropdown {
      right: 0;
      left: initial;
    }
  }
  @media print {
    .lh-topbar {
      position: static;
      margin-left: 0;
    }

    .lh-tools__dropdown {
      display: none;
    }
  }
